const $ = (s, root = document) => root.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const glyph = {home:'f015',bowl:'e4c6',wand:'e2ca',book:'f02e',user:'f007',search:'f002',bell:'f0f3',arrow:'f061',back:'f060',clock:'f017',star:'f005',gauge:'f625',fridge:'f291',filter:'f1de',close:'f00d',plus:'f067',minus:'f068',fire:'f06d',check:'f00c',utensils:'f2e7',leaf:'f06c'};
function icon(name, regular=false){return `<i class="icon${regular?' regular':''}" aria-hidden="true">&#x${glyph[name]||glyph.bowl};</i>`;}
const photo = (url, extra='') => `<div class="photo ${extra}" style="background-image:url('${esc(url)}')" role="img" aria-label="Yemek fotoğrafı"></div>`;
const params = new URLSearchParams(location.search);
const page = document.body.dataset.page;
const link = r => `tarif-detay.html?tarif=${encodeURIComponent(r.slug)}&donus=${encodeURIComponent(location.pathname.split('/').pop()+location.search)}`;
let saved; try{saved=JSON.parse(localStorage.getItem('dadagastro-prototype-saved')||'[]');if(!Array.isArray(saved))saved=[];}catch{saved=[];}
function saveButton(r,extra=''){return `<button type="button" class="save ${extra}" data-save="${esc(r.slug)}" aria-label="${saved.includes(r.slug)?'Kaydı kaldır':'Tarifi kaydet'}" aria-pressed="${saved.includes(r.slug)}">${icon('book',!saved.includes(r.slug))}</button>`;}
function rating(r){return r.rating?`<span class="rating">${icon('star')} ${Number(r.rating).toFixed(1).replace('.',',')}</span>`:'<span class="muted">Puan yok</span>';}
function card(r){return `<article class="recipe-card"><a class="card-link" href="${link(r)}">${photo(r.image,'card-photo')}<div class="card-body"><span class="card-category">${esc(r.category)}</span><h3>${esc(r.title)}</h3><div class="meta"><span>${icon('clock')} ${r.minutes} dk</span><span>${icon('gauge')} ${esc(r.difficulty||'—')}</span></div><div class="card-foot"><span class="card-author">${esc(r.author)}</span>${rating(r)}</div></div></a>${saveButton(r)}</article>`;}
function nav(){return `<nav class="bottom-nav" aria-label="Alt menü">${[['home','Ana Sayfa','index.html',page==='index'],['bowl','Tarifler','tarifler.html',page!=='index'],['wand','Ne Pişirsem','',false],['book','Defterim','',false],['user','Profil','',false]].map(([i,t,url,active],n)=>`<a href="${url}" class="nav-item ${active?'active':''} ${n===2?'center':''}" ${active?'aria-current="page"':''}>${n===2?`<span class="fab">${icon(i)}</span>`:icon(i)}<span>${t}</span></a>`).join('')}</nav>`;}
function renderTop(title){return `<header class="topbar">${title?`<a class="icon-button" href="index.html" aria-label="Ana sayfaya dön">${icon('back')}</a><h1 class="top-title">${title}</h1>`:'<a class="wordmark" href="index.html" aria-label="DadaGastro ana sayfa"><b>dada</b>gastro</a>'}<a class="icon-button" href="" aria-label="Bildirimler">${icon('bell',true)}</a></header>`;}
function search(value='',id='search'){return `<form class="search-box" role="search" action="tarifler.html">${icon('search')}<input type="search" id="${id}" name="q" aria-label="Tarif ara" placeholder="Bugün ne pişirmek istersin?" value="${esc(value)}" autocomplete="off"></form>`;}
function sectionHead(title,href='',label='Tümünü gör'){return `<div class="section-head"><h2>${title}</h2><a href="${href}">${label} ${icon('arrow')}</a></div>`;}
function home(){const day=DATA.recipes.find(r=>r.slug===DATA.daySlug)||DATA.recipes[0];const names=['Tavuk ve Hindi','Çorba','Sebze','Tatlı','Kahvaltılık','Balık ve Deniz Ürünleri'];const cats=names.map(n=>DATA.categories.find(c=>c.name===n)).filter(Boolean);return `${renderTop()}<main><div class="intro"><span class="eyebrow">Herkesin bir tabağı var</span><h1>Bugün ne pişirsem?</h1>${search()}<div class="quick-links"><a href="" class="quick">${icon('wand')}<div><b>Ne pişirsem?</b><small>Birlikte seçelim</small></div></a><a href="" class="quick">${icon('fridge')}<div><b>Dolapta ne var?</b><small>Elindekilerle pişir</small></div></a></div></div><section class="section">${sectionHead('Kategoriler','tarifler.html','Keşfet')}<div class="rail categories">${cats.map(c=>`<a href="tarifler.html?kategori=${encodeURIComponent(c.name)}" class="category">${photo(c.image)}<span>${esc(c.name)}</span></a>`).join('')}</div></section><section class="section">${sectionHead('Günün tarifi','tarifler.html')}<article class="daily"><a href="${link(day)}">${photo(day.image)}<span class="daily-label">${icon('star')} Bugünün lezzeti</span><div class="daily-body"><span class="eyebrow">${esc(day.category)}</span><h3>${esc(day.title)}</h3><div class="meta"><span>${icon('clock')} ${day.minutes} dk</span><span>${icon('gauge')} ${esc(day.difficulty)}</span>${rating(day)}</div></div></a>${saveButton(day)}</article></section><section class="section">${sectionHead('Öne çıkan tarifler','tarifler.html')}<div class="rail">${DATA.recipes.slice(0,5).map(card).join('')}</div></section><section class="section">${sectionHead('Küçük sırlar, büyük fark')}<div class="rail">${DATA.tips.map(t=>`<a href="" class="tip">${photo(t.image)}<div class="tip-body"><span class="eyebrow">Püf noktası</span><h3>${esc(t.title)}</h3></div></a>`).join('')}</div></section><section class="section">${sectionHead('Tarifin ustaları')}<div class="rail">${DATA.recipes.slice(0,5).map(r=>`<a href="" class="chef"><div class="avatar">${esc(r.author.slice(0,1))}</div><span>${esc(r.author)}</span><small>Tarifin ustası</small></a>`).join('')}</div></section></main>${nav()}`;}
let query=params.get('q')||'',category=params.get('kategori')||'',difficulty=params.get('zorluk')||'',duration=params.get('sure')||'',sort=params.get('sirala')||'onerilen';
function list(){return `${renderTop('Tarifler')}<main><div class="list-tools">${search(query)}<div class="chips" aria-label="Kategoriler">${['',...new Set(DATA.recipes.map(r=>r.category))].map(c=>`<button class="chip ${category===c?'active':''}" data-category="${esc(c)}" aria-pressed="${category===c}">${esc(c||'Tümü')}</button>`).join('')}</div></div><div class="list-content"><div class="result-bar"><p id="resultCount" role="status"></p><button class="filter-button" id="openFilters">${icon('filter')} Filtrele / Sırala</button></div><div class="recipe-list" id="results"></div></div></main>${nav()}<dialog class="sheet" id="filters" aria-labelledby="filterTitle"><div class="handle"></div><div class="sheet-head"><h2 id="filterTitle">Tam sana göre</h2><button class="icon-button" id="closeFilters" aria-label="Filtreleri kapat">${icon('close')}</button></div><form id="filterForm"><label for="duration">Ne kadar vaktin var?</label><select id="duration"><option value="">Tüm süreler</option><option value="30">30 dakika ve altı</option><option value="60">60 dakika ve altı</option></select><label for="difficulty">Zorluk</label><select id="difficulty"><option value="">Tüm seviyeler</option><option>Çok Kolay</option><option>Kolay</option><option>Orta</option><option>Zor</option></select><label for="sort">Sıralama</label><select id="sort"><option value="onerilen">Önerilen</option><option value="en_hizli">En hızlı</option><option value="puan">En yüksek puan</option></select><div class="sheet-actions"><button type="button" class="button secondary" id="resetFilters">Temizle</button><button class="button">Tarifleri göster</button></div></form></dialog>`;}
function syncQuery(){const p=new URLSearchParams();for(const [key,value] of Object.entries({q:query,kategori:category,zorluk:difficulty,sure:duration,sirala:sort==='onerilen'?'':sort}))if(value)p.set(key,value);history.replaceState(null,'','tarifler.html'+(p.size?'?'+p:''));}
function renderResults(){let rs=DATA.recipes.filter(r=>(!query||r.title.toLocaleLowerCase('tr').includes(query.toLocaleLowerCase('tr')))&&(!category||r.category===category)&&(!difficulty||r.difficulty===difficulty)&&(!duration||r.minutes<=Number(duration)));if(sort==='en_hizli')rs.sort((a,b)=>a.minutes-b.minutes);if(sort==='puan')rs.sort((a,b)=>Number(b.rating)-Number(a.rating));$('#resultCount').innerHTML=`<b>${rs.length}</b> tarif seni bekliyor`;$('#results').innerHTML=rs.length?rs.map(card).join(''):`<div class="empty">${icon('search')}<h2>Bir de böyle deneyelim</h2><p>Bu arama ve filtrelere uygun tarif yok. Seçimlerini temizleyip yeniden keşfet.</p><button class="button" data-clear>Tüm tarifleri göster</button></div>`;document.querySelectorAll('[data-category]').forEach(b=>{b.classList.toggle('active',b.dataset.category===category);b.setAttribute('aria-pressed',b.dataset.category===category)});syncQuery();}
function loading(){ $('#resultCount').textContent='Tarifler yükleniyor';$('#results').innerHTML='<p class="loading-label" role="status">Sofrana yeni lezzetler geliyor…</p>'+Array(4).fill('<div class="skeleton" aria-hidden="true"></div>').join('');}
let recipe,scale=1;
function detail(){recipe=DATA.recipes.find(r=>r.slug===(params.get('tarif')||DATA.recipes[0].slug));if(!recipe)return `${renderTop('Tarif bulunamadı')}<main class="section"><div class="empty"><h2>Bu tarif burada yok</h2><p>Diğer tarifleri keşfedebilirsin.</p><a href="tarifler.html" class="button">Tariflere dön</a></div></main>${nav()}`;const r=recipe;document.title=r.title+' · DadaGastro';const ret=params.get('donus');const back=ret&&/^(index|tarifler)\.html(?:\?|$)/.test(ret)?ret:'tarifler.html';return `<header class="topbar"><a href="${esc(back)}" class="icon-button" aria-label="Geri dön">${icon('back')}</a><span class="top-title">Tarif defteri</span><button class="icon-button" data-save="${esc(r.slug)}" aria-pressed="${saved.includes(r.slug)}" aria-label="Tarifi kaydet">${icon('book',!saved.includes(r.slug))}</button></header><main><div class="detail-hero photo" style="background-image:url('${esc(r.image)}')" role="img" aria-label="${esc(r.title)}"><span class="hero-tag">${esc(r.category)}</span></div><div class="detail-main"><h1>${esc(r.title)}</h1><div class="author-row"><a href="" class="avatar" aria-label="${esc(r.author)} profili">${esc(r.author.slice(0,1))}</a><a href="">${esc(r.author)}</a><span class="rating">${r.rating?`${icon('star')} ${Number(r.rating).toFixed(1).replace('.',',')} <span class="muted">(${r.ratingCount})</span>`:'Henüz puan yok'}</span></div><div class="summary"><div>${icon('clock')}<b>${r.minutes} dk</b><small>Toplam süre</small></div><div>${icon('gauge')}<b>${esc(r.difficulty||'—')}</b><small>Zorluk</small></div><div>${icon('utensils')}<b><span data-portions>${r.servings}</span> ${esc(r.unit)}</b><small>Porsiyon</small></div></div><p class="subtitle">${esc(r.description)}</p><section class="detail-block"><div class="ingredients-head"><h2>Malzemeler</h2><div class="stepper" aria-label="Porsiyon ayarı"><button id="less" aria-label="Porsiyonu azalt">${icon('minus')}</button><output id="portions" aria-live="polite">${r.servings}</output><button id="more" aria-label="Porsiyonu artır">${icon('plus')}</button></div></div><p class="portion-note"><span id="scaleLabel">1×</span> ölçü · Hazır olan malzemeleri işaretle.</p><ul class="ingredients">${r.ingredients.map((ing,i)=>`<li><label class="ingredient"><input type="checkbox" aria-label="${esc(ing.name)} hazır"><span class="ingredient-name">${esc(ing.name)}</span><span class="amount"><span data-amount="${i}">${ing.amount===null?'':ing.amount.toLocaleString('tr')}</span> ${esc(ing.unit)}</span></label></li>`).join('')}</ul></section><section class="detail-block" id="adimlar"><div class="section-head"><h2>Nasıl yapılır?</h2><span class="muted">${r.steps.length} adım</span></div><ol class="steps">${r.steps.map((s,i)=>`<li class="step"><span class="step-index">${i+1}</span><div><h3>${esc(s.title)}</h3><p>${esc(s.body)}</p>${s.time?`<span class="step-time">${icon('clock')} ${esc(s.time)}</span>`:''}</div></li>`).join('')}</ol></section><section class="detail-block"><h2>Yorumlar (${r.reviews.length})</h2>${r.reviews.length?r.reviews.map(v=>`<article class="review"><div class="review-head"><b>${esc(v.author)}</b><span class="rating">${icon('star')} ${v.rating}</span></div><p>${esc(v.body)}</p><small class="muted">${esc(v.date)}</small></article>`).join(''):'<div class="review-empty">Henüz yorum yok. Deneyimini paylaşmak için <a href=""><u>giriş yap</u></a>.</div>'}</section></div></main><div class="cook-bar"><button class="button" id="startCooking">${icon('fire')} Pişirmeye Başla ${icon('arrow')}</button></div>${nav()}`;}
$('#app').innerHTML=`<div class="app-shell ${page==='tarif-detay'?'detail-shell':''}">${page==='index'?home():page==='tarifler'?list():detail()}</div><div class="toast" role="status" hidden></div>`;
let toastTimer;function toast(message){const el=$('.toast');el.textContent=message;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,2800);}
document.addEventListener('click',e=>{const btn=e.target.closest('[data-save]');if(btn){const id=btn.dataset.save;saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];let persisted=true;try{localStorage.setItem('dadagastro-prototype-saved',JSON.stringify(saved));}catch{persisted=false;}document.querySelectorAll('[data-save]').forEach(b=>{const on=saved.includes(b.dataset.save);b.setAttribute('aria-pressed',on);b.setAttribute('aria-label',on?'Kaydı kaldır':'Tarifi kaydet');b.innerHTML=icon('book',!on);});toast(persisted?(saved.includes(id)?'Bu cihazda kaydedildi':'Kayıt kaldırıldı'):'Kayıt yalnız bu oturumda tutuluyor');}const emptyLink=e.target.closest('a[href=""]');if(emptyLink){e.preventDefault();toast('Bu bölüm sonraki adımda.');}if(e.target.closest('[data-clear]')){query=category=difficulty=duration='';sort='onerilen';$('#search').value='';renderResults();}});
if(page==='tarifler'){if(params.get('durum')==='yukleniyor')loading();else renderResults();let debounce;$('#search').addEventListener('input',e=>{query=e.target.value;loading();clearTimeout(debounce);debounce=setTimeout(renderResults,220);});$('.search-box').addEventListener('submit',e=>{e.preventDefault();clearTimeout(debounce);renderResults();$('#search').blur();});document.querySelectorAll('[data-category]').forEach(b=>b.addEventListener('click',()=>{category=b.dataset.category;renderResults();}));const dialog=$('#filters');$('#openFilters').onclick=()=>{$('#duration').value=duration;$('#difficulty').value=difficulty;$('#sort').value=sort;dialog.showModal();document.body.style.overflow='hidden';};const close=()=>{dialog.close();document.body.style.overflow='';};$('#closeFilters').onclick=close;dialog.addEventListener('close',()=>document.body.style.overflow='');dialog.addEventListener('click',e=>{if(e.target===dialog&&e.clientY<dialog.getBoundingClientRect().top)close();});$('#filterForm').onsubmit=e=>{e.preventDefault();duration=$('#duration').value;difficulty=$('#difficulty').value;sort=$('#sort').value;renderResults();close();};$('#resetFilters').onclick=()=>{$('#duration').value=$('#difficulty').value='';$('#sort').value='onerilen';};}
if(page==='tarif-detay'&&recipe){function updateScale(){const portions=Math.round(recipe.servings*scale);$('#portions').textContent=portions;document.querySelectorAll('[data-portions]').forEach(e=>e.textContent=portions);$('#scaleLabel').textContent=scale.toLocaleString('tr')+'×';document.querySelectorAll('[data-amount]').forEach(e=>{const amount=recipe.ingredients[Number(e.dataset.amount)].amount;e.textContent=amount===null?'':(amount*scale).toLocaleString('tr',{maximumFractionDigits:2});});$('#less').disabled=scale===.5;$('#more').disabled=scale===1.5;}$('#less').onclick=()=>{scale=Math.max(.5,scale-.5);updateScale();};$('#more').onclick=()=>{scale=Math.min(1.5,scale+.5);updateScale();};$('#startCooking').onclick=()=>{$('#adimlar').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});const heading=$('#adimlar h2');heading.tabIndex=-1;heading.focus({preventScroll:true});};updateScale();}
